import { useState } from 'react'

import { useAtom } from 'jotai'

import { Opacity } from '@mui/icons-material'
import { Box, IconButton, Popover, Slider, Typography } from '@mui/material'

import { appOpacityAtom } from '../atoms/opacity'

export function OpacityControl() {
  const [appOpacity, setAppOpacity] = useAtom(appOpacityAtom)
  const [anchor, setAnchor] = useState<HTMLButtonElement | null>(null)

  return (
    <>
      <IconButton color="inherit" onClick={(e) => setAnchor(e.currentTarget)} sx={{ mr: 1 }}>
        <Opacity />
      </IconButton>
      <Popover
        open={Boolean(anchor)}
        anchorEl={anchor}
        onClose={() => setAnchor(null)}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
        transformOrigin={{ vertical: 'top', horizontal: 'center' }}
      >
        <Box sx={{ px: 3, py: 2, width: 180 }}>
          <Typography variant="caption" gutterBottom display="block">
            Opacity
          </Typography>
          <Slider
            value={appOpacity}
            onChange={(_, val) => setAppOpacity(val as number)}
            min={0.1}
            max={1}
            step={0.05}
            size="small"
            valueLabelDisplay="auto"
            valueLabelFormat={(v) => `${Math.round(v * 100)}%`}
          />
        </Box>
      </Popover>
    </>
  )
}
