import { createTheme, type PaletteMode } from '@mui/material/styles'

export function createAppTheme(mode: PaletteMode) {
  return createTheme({
    palette: {
      mode,
      primary: {
        main: mode === 'dark' ? '#90caf9' : '#1976d2',
      },
      secondary: {
        main: mode === 'dark' ? '#ce93d8' : '#9c27b0',
      },
      success: {
        main: mode === 'dark' ? '#81c784' : '#2e7d32',
        light: '#a5d6a7',
      },
      error: {
        main: mode === 'dark' ? '#f44336' : '#d32f2f',
        light: '#e57373',
      },
      warning: {
        main: mode === 'dark' ? '#ffa726' : '#ed6c02',
        light: '#ffb74d',
      },
      background: {
        default: mode === 'dark' ? '#121212' : '#f5f5f5',
        paper: mode === 'dark' ? '#1e1e1e' : '#ffffff',
      },
    },
    typography: {
      fontFamily: '"Roboto", "Helvetica", "Arial", sans-serif',
    },
    components: {
      MuiButton: {
        styleOverrides: {
          root: {
            textTransform: 'none',
          },
        },
      },
      MuiAlert: {
        styleOverrides: {
          root: ({ theme, ownerState }) => ({
            // 다크 모드에서 기본(standard) variant만 어둡게 처리한다.
            // filled/outlined variant는 severity 색상을 유지해야 하므로 제외한다.
            ...(theme.palette.mode === 'dark' &&
              ownerState.variant === 'standard' && {
                backgroundColor: theme.palette.grey[900],
              }),
          }),
        },
      },
    },
  })
}
