import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from 'react'

import type { User, Session } from '@supabase/supabase-js'
import { useAtom } from 'jotai'

import { activeSudoUserAtom, toImpersonatedUser, toSavedSudoUser } from '@/atoms/sudoUsers'
import { supabase } from '@/lib/supabase'

interface AuthContextType {
  user: User | null // This will be the effective user (impersonated || real)
  realUser: User | null // The actual logged-in user
  session: Session | null
  loading: boolean
  signInWithGitHub: () => Promise<void>
  signOut: () => Promise<void>
  impersonatedUser: User | null
  setImpersonatedUser: (user: User | null) => void
  isAdmin: boolean
}

const AuthContext = createContext<AuthContextType | undefined>(undefined)

export declare namespace AuthProvider {
  export type Props = {
    userOnly?: boolean
    children: ReactNode
  }
}

const ADMIN_EMAILS = ['sungwoo.cho.dev@gmail.com']

export function AuthProvider({ userOnly, children }: AuthProvider.Props) {
  const [realUser, setRealUser] = useState<User | null>(null)
  const [activeSudoUser, setActiveSudoUser] = useAtom(activeSudoUserAtom)
  const [session, setSession] = useState<Session | null>(null)
  const [loading, setLoading] = useState(true)

  const isAdmin = realUser ? ADMIN_EMAILS.includes(realUser.email ?? '') : false

  // 저장된 sudo 대상은 admin으로 로그인된 동안에만 적용한다.
  const impersonatedUser = useMemo(
    () => (isAdmin && activeSudoUser ? toImpersonatedUser(activeSudoUser) : null),
    [isAdmin, activeSudoUser]
  )

  const setImpersonatedUser = useCallback(
    (target: User | null) => {
      setActiveSudoUser(target ? toSavedSudoUser(target) : null)
    },
    [setActiveSudoUser]
  )

  const user = impersonatedUser || realUser

  // admin이 아닌 사용자로 로그인되면 남아있는 sudo 상태를 정리한다.
  useEffect(() => {
    if (realUser && !isAdmin && activeSudoUser) {
      setActiveSudoUser(null)
    }
  }, [realUser, isAdmin, activeSudoUser, setActiveSudoUser])

  useEffect(() => {
    // 현재 세션 가져오기
    if (userOnly) {
      // Storybook/testing: set a mock user synchronously without network requests
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setRealUser({
        id: 'mock-user-id',
        aud: 'authenticated',
        role: 'authenticated',
        email: 'test@example.com',
        email_confirmed_at: '2024-01-01T00:00:00Z',
        phone: '',
        confirmed_at: '2024-01-01T00:00:00Z',
        last_sign_in_at: '2024-01-01T00:00:00Z',
        app_metadata: { provider: 'github' },
        user_metadata: {
          avatar_url: 'https://avatars.githubusercontent.com/u/1?v=4',
          full_name: 'Test User',
          user_name: 'testuser',
        },
        identities: [],
        created_at: '2024-01-01T00:00:00Z',
        updated_at: '2024-01-01T00:00:00Z',
      } as User)
      setLoading(false)
    } else {
      supabase.auth.getSession().then(({ data: { session } }) => {
        // console.log('현재 세션:', session)
        setSession(session)
        setRealUser(session?.user ?? null)
        setLoading(false)
      })
    }

    // 인증 상태 변경 구독
    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((_event, session) => {
      if (userOnly) {
        return
      }
      // console.log('onAuthStateChange:', _event, session?.provider_token, session)

      setSession(session)
      setRealUser(session?.user ?? null)
      setLoading(false)
    })

    return () => subscription.unsubscribe()
  }, [userOnly])

  async function signInWithGitHub() {
    // const redirectUrl = import.meta.env.PROD
    //   ? 'https://training-buddy.github.io'
    //   : window.location.origin
    const redirectUrl = window.location.origin

    // console.log({ redirectUrl })
    const { error } = await supabase.auth.signInWithOAuth({
      provider: 'github',
      options: {
        redirectTo: redirectUrl,
        scopes: 'repo read:org',
      },
    })
    if (error) {
      // eslint-disable-next-line no-console
      console.error('GitHub 로그인 오류:', error.message)
      throw error
    }
  }

  async function signOut() {
    const { error } = await supabase.auth.signOut()
    if (error) {
      // eslint-disable-next-line no-console
      console.error('로그아웃 오류:', error.message)
      throw error
    }
    setImpersonatedUser(null)
  }

  return (
    <AuthContext.Provider
      value={{
        user,
        realUser,
        session,
        loading,
        signInWithGitHub,
        signOut,
        impersonatedUser,
        setImpersonatedUser,
        isAdmin,
      }}
    >
      {children}
    </AuthContext.Provider>
  )
}

// eslint-disable-next-line react-refresh/only-export-components
export function useAuth() {
  const context = useContext(AuthContext)
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider')
  }
  return context
}
