import type { User } from '@supabase/supabase-js'

import { atomWithStorageForSpa } from '@/atoms/utils-atom'

export interface SavedSudoUser {
  id: string
  full_name: string
  user_name: string
}

const SAVED_SUDO_USERS_KEY = 'training-buddy:saved-sudo-users'
const ACTIVE_SUDO_USER_KEY = 'training-buddy:active-sudo-user'

export const savedSudoUsersAtom = atomWithStorageForSpa<SavedSudoUser[]>(SAVED_SUDO_USERS_KEY, [])

/** 현재 전환(sudo) 중인 사용자. 새로고침 후에도 유지되도록 localStorage에 보관한다. */
export const activeSudoUserAtom = atomWithStorageForSpa<SavedSudoUser | null>(
  ACTIVE_SUDO_USER_KEY,
  null
)

/** localStorage에 보관된 최소 정보를 Supabase User 형태로 복원한다. */
export function toImpersonatedUser(saved: SavedSudoUser): User {
  return {
    id: saved.id,
    user_metadata: {
      full_name: saved.full_name,
      user_name: saved.user_name,
    },
  } as unknown as User
}

export function toSavedSudoUser(user: User): SavedSudoUser {
  return {
    id: user.id,
    full_name: user.user_metadata?.full_name ?? user.id,
    user_name: user.user_metadata?.user_name ?? '',
  }
}
