import { useState } from 'react'

import type { User } from '@supabase/supabase-js'
import { useAtom } from 'jotai'

import {
  Logout as LogoutIcon,
  PersonSearch as PersonSearchIcon,
  RecordVoiceOver as SudoIcon,
  Delete as DeleteIcon,
} from '@mui/icons-material'
import {
  Avatar,
  Box,
  IconButton,
  Menu,
  MenuItem,
  Typography,
  Divider,
  Dialog,
  DialogTitle,
  DialogContent,
  TextField,
  DialogActions,
  Button,
  Badge,
  List,
  ListItem,
  ListItemButton,
  ListItemText,
} from '@mui/material'

import { savedSudoUsersAtom, type SavedSudoUser } from '@/atoms/sudoUsers'
import { supabase } from '@/lib/supabase'

import { useAuth } from '../contexts/AuthContext'

export function UserMenu() {
  const { realUser, signOut, isAdmin, impersonatedUser, setImpersonatedUser } = useAuth()
  const [anchorEl, setAnchorEl] = useState<null | HTMLElement>(null)
  const [sudoDialogOpen, setSudoDialogOpen] = useState(false)
  const [targetUserId, setTargetUserId] = useState('')
  const [savedUsers, setSavedUsers] = useAtom(savedSudoUsersAtom)
  const [isLoading, setIsLoading] = useState(false)

  if (!realUser) return null

  const handleOpen = (event: React.MouseEvent<HTMLElement>) => {
    setAnchorEl(event.currentTarget)
  }

  const handleClose = () => {
    setAnchorEl(null)
  }

  const handleSignOut = async () => {
    handleClose()
    await signOut()
  }

  const handleOpenSudo = () => {
    handleClose()
    setSudoDialogOpen(true)
  }

  const handleCloseSudo = () => {
    setSudoDialogOpen(false)
    setTargetUserId('')
  }

  const saveUser = (user: SavedSudoUser) => {
    const updated = [user, ...savedUsers.filter((u) => u.id !== user.id)].slice(0, 10)
    setSavedUsers(updated)
  }

  const deleteSavedUser = (id: string) => {
    const updated = savedUsers.filter((u) => u.id !== id)
    setSavedUsers(updated)
  }

  const applySudo = (user: SavedSudoUser) => {
    setImpersonatedUser({
      id: user.id,
      user_metadata: {
        full_name: user.full_name,
        user_name: user.user_name,
      },
    } as unknown as User)
    setSudoDialogOpen(false)
    setTargetUserId('')
  }

  const handleApplySudo = async () => {
    if (!targetUserId) return

    // Check if already in saved users
    const existing = savedUsers.find((u) => u.id === targetUserId)
    if (existing) {
      applySudo(existing)
      return
    }

    setIsLoading(true)
    try {
      // Fetch metadata using RPC
      const { data: metadata, error } = await supabase.rpc('get_user_metadata_by_id', {
        target_user_id: targetUserId,
      })

      if (error) throw error

      const newUser: SavedSudoUser = {
        id: targetUserId,
        full_name: metadata?.preferred_username || `User ${targetUserId.slice(0, 5)} (SUDO)`,
        user_name: metadata?.user_name || `sudo_${targetUserId.slice(0, 5)}`,
      }

      saveUser(newUser)
      applySudo(newUser)
    } catch (e) {
      // eslint-disable-next-line no-console
      console.error('Failed to fetch user metadata', e)
      // Fallback if user not found or RPC fails
      const fallbackUser: SavedSudoUser = {
        id: targetUserId,
        full_name: `Unknown ${targetUserId.slice(0, 5)} (SUDO)`,
        user_name: `sudo_${targetUserId.slice(0, 5)}`,
      }
      saveUser(fallbackUser)
      applySudo(fallbackUser)
    } finally {
      setIsLoading(false)
    }
  }

  const handleStopSudo = () => {
    setImpersonatedUser(null)
    handleClose()
  }

  const avatarUrl = realUser.user_metadata?.avatar_url
  const displayName =
    realUser.user_metadata?.full_name || realUser.user_metadata?.user_name || realUser.email

  return (
    <Box>
      <IconButton onClick={handleOpen} size="small">
        <Badge
          overlap="circular"
          anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
          badgeContent={
            impersonatedUser ? <SudoIcon sx={{ fontSize: 12, color: 'warning.main' }} /> : null
          }
        >
          <Avatar src={avatarUrl} alt={displayName} sx={{ width: 32, height: 32 }}>
            {displayName?.[0]?.toUpperCase()}
          </Avatar>
        </Badge>
      </IconButton>
      <Menu
        anchorEl={anchorEl}
        open={Boolean(anchorEl)}
        onClose={handleClose}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
        transformOrigin={{ vertical: 'top', horizontal: 'right' }}
      >
        <Box sx={{ px: 2, py: 1 }}>
          <Typography variant="subtitle2">{displayName}</Typography>
          <Typography variant="body2" color="text.secondary">
            {realUser.email}
          </Typography>
          {impersonatedUser && (
            <Box sx={{ mt: 1, p: 0.5, bgcolor: 'warning.light', borderRadius: 1 }}>
              <Typography variant="caption" color="warning.contrastText" fontWeight="bold">
                Acting as: {impersonatedUser.user_metadata?.full_name || impersonatedUser.id}
              </Typography>
            </Box>
          )}
        </Box>
        <Divider />
        {isAdmin && (
          <MenuItem onClick={handleOpenSudo}>
            <PersonSearchIcon fontSize="small" sx={{ mr: 1 }} />
            사용자 전환 (Sudo)
          </MenuItem>
        )}
        {impersonatedUser && (
          <MenuItem onClick={handleStopSudo}>
            <LogoutIcon fontSize="small" sx={{ mr: 1, color: 'error.main' }} />
            Sudo 중단
          </MenuItem>
        )}
        <Divider />
        <MenuItem onClick={handleSignOut}>
          <LogoutIcon fontSize="small" sx={{ mr: 1 }} />
          로그아웃
        </MenuItem>
      </Menu>

      <Dialog open={sudoDialogOpen} onClose={handleCloseSudo} maxWidth="sm" fullWidth>
        <DialogTitle>사용자 전환 (Sudo Mode)</DialogTitle>
        <DialogContent dividers>
          <Box sx={{ mb: 3 }}>
            <Typography variant="body2" sx={{ mb: 1 }}>
              전환할 사용자의 ID (UUID)를 입력하세요.
            </Typography>
            <Box sx={{ display: 'flex', gap: 1 }}>
              <TextField
                autoFocus
                margin="dense"
                label="User ID"
                type="text"
                fullWidth
                variant="outlined"
                size="small"
                value={targetUserId}
                onChange={(e) => setTargetUserId(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleApplySudo()}
              />
              <Button
                onClick={handleApplySudo}
                variant="contained"
                color="warning"
                disabled={!targetUserId || isLoading}
                sx={{ mt: 1, minWidth: '100px', height: '40px' }}
              >
                {isLoading ? '...' : '전환'}
              </Button>
            </Box>
          </Box>

          {savedUsers.length > 0 && (
            <Box>
              <Typography variant="subtitle2" sx={{ mb: 1 }}>
                최근 사용한 목록
              </Typography>
              <List dense>
                {savedUsers.map((user) => (
                  <ListItem
                    key={user.id}
                    disablePadding
                    secondaryAction={
                      <IconButton
                        edge="end"
                        size="small"
                        onClick={(e) => {
                          e.stopPropagation()
                          deleteSavedUser(user.id)
                        }}
                      >
                        <DeleteIcon fontSize="small" />
                      </IconButton>
                    }
                  >
                    <ListItemButton
                      onClick={() => applySudo(user)}
                      sx={{
                        borderRadius: 1,
                        '&:hover': { bgcolor: 'action.hover' },
                      }}
                    >
                      <ListItemText
                        primary={user.full_name}
                        secondary={user.id}
                        primaryTypographyProps={{ variant: 'body2', fontWeight: 'bold' }}
                        secondaryTypographyProps={{ variant: 'caption' }}
                      />
                    </ListItemButton>
                  </ListItem>
                ))}
              </List>
            </Box>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseSudo}>취소</Button>
        </DialogActions>
      </Dialog>
    </Box>
  )
}
